{"path":"about.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>About — {{BUSINESS_NAME}}</title>
  <meta name="description" content="A calm, precise approach to group sound sessions and restorative practice in {{CITY}}, {{STATE}}.">
  <style>
    :root{--bg:#f6fbfb;--panel:#ffffff;--muted:#6b7280;--accent:#2c7a7b;--accent-2:#6dd3d2;--glass:rgba(255,255,255,0.6);--shadow:0 6px 18px rgba(36,59,64,0.08);font-family:Inter, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;color:#08303a}
    *{box-sizing:border-box}
    body{margin:0;background:linear-gradient(180deg,var(--bg),#f1f8f8);min-height:100vh}
    header{backdrop-filter:blur(6px);background:linear-gradient(90deg,rgba(255,255,255,0.6),rgba(255,255,255,0.4));border-bottom:1px solid rgba(10,30,30,0.03)}
    .wrap{max-width:1100px;margin:0 auto;padding:28px}
    nav{display:flex;gap:18px;align-items:center}
    .brand{font-weight:700;color:var(--accent);letter-spacing:0.2px}
    nav a{color:#054145;text-decoration:none;padding:8px 10px;border-radius:8px;font-weight:600}
    nav a.active{background:var(--accent-2);color:#003437}
    main{padding:36px 18px}
    .grid{display:grid;grid-template-columns:1fr 360px;gap:28px;max-width:1100px;margin:0 auto}
    .panel{background:var(--panel);padding:22px;border-radius:12px;box-shadow:var(--shadow)}
    h1{margin:0 0 8px;font-size:28px;color:#063238}
    p.lead{margin:0 0 14px;color:var(--muted);line-height:1.5}
    .mission{display:flex;gap:12px;align-items:flex-start}
    .svg-wrap{width:88px;height:88px;border-radius:12px;background:linear-gradient(135deg,var(--accent-2),var(--accent));display:flex;align-items:center;justify-content:center;color:white;font-weight:700}
    .meta{font-size:14px;color:var(--muted)}
    /* proof gallery */
    .proof{margin-top:18px}
    .testimonial{min-height:88px;display:flex;flex-direction:column;gap:8px;transition:opacity 420ms ease,transform 420ms ease}
    .testimonial p{margin:0;color:#053238}
    .author{font-size:13px;color:var(--muted)}
    .badges{display:flex;gap:8px;margin-top:10px}
    .badge{background:linear-gradient(180deg,#ffffff,#f0f7f7);padding:8px 10px;border-radius:10px;font-weight:600;color:#064047;position:relative;cursor:default}
    .badge[data-tip]:hover::after,.badge[data-tip]:focus::after{content:attr(data-tip);position:absolute;left:50%;transform:translateX(-50%);top:-36px;background:#063238;color:white;padding:8px 10px;border-radius:8px;font-size:12px;white-space:nowrap}
    .controls{display:flex;gap:8px;margin-top:12px}
    .dot{width:10px;height:10px;border-radius:50%;background:#c7e7e6;cursor:pointer}
    .dot.active{background:var(--accent)}
    /* aside */
    aside h3{margin:0 0 8px}
    .info-list{display:grid;gap:10px}
    .info{display:flex;gap:10px;align-items:center}
    .kbd{background:#eefaf9;padding:6px 8px;border-radius:8px;color:var(--accent);font-weight:700}
    footer{max-width:1100px;margin:28px auto;padding:22px;color:var(--muted);font-size:13px}
    .cta{display:inline-block;background:var(--accent);color:white;padding:10px 14px;border-radius:10px;text-decoration:none;font-weight:700}
  </style>
</head>
<body>
  <header>
    <div class="wrap">
      <nav>
        <div class="brand">{{BUSINESS_NAME}}</div>
        <div style="flex:1"></div>
        <a href="index.html">Home</a>
        <a href="events.html">Sessions</a>
        <a href="private-sessions.html">Private</a>
        <a href="pricing.html">Rates</a>
        <a href="about.html" class="active">Our Story</a>
        <a href="faq.html">FAQ</a>
        <a href="book.html">Reserve</a>
        <a href="contact.html">Contact</a>
      </nav>
    </div>
  </header>
  <main>
    <div class="grid">
      <section>
        <div class="panel">
          <div class="mission">
            <div class="svg-wrap">SB</div>
            <div>
              <h1>We craft quiet structure for attentive listening</h1>
              <p class="lead">Our group sound gatherings are designed to support gentle recalibration and steady focus — simple, consistent sessions in {{CITY}}, {{STATE}}. Membership gives priority access and a predictable rhythm for practice.</p>
              <div class="meta">Membership benefits include priority booking, two make-ups per quarter, and a monthly member-only evening.</div>
            </div>
          </div>

          <div class="proof" aria-live="polite">
            <h3 style="margin-top:18px;margin-bottom:6px">What people notice</h3>
            <div id="testimonial" class="testimonial">
              <p id="t-text">"I leave clearer and less reactive — a quieter baseline that lasts a few days."</p>
              <div class="author" id="t-author">— L., member</div>
            </div>
            <div class="controls">
              <div id="dots"></div>
              <div style="flex:1"></div>
              <div class="badges">
                <div class="badge" tabindex="0" data-tip="Sessions guided by certified practitioners">Certified</div>
                <div class="badge" tabindex="0" data-tip="Background checks and safe-space policies">Verified</div>
                <div class="badge" tabindex="0" data-tip="Peer-reviewed comfort and accessibility guidelines">Accessible</div>
              </div>
            </div>
          </div>

          <div style="margin-top:18px;font-size:13px;color:var(--muted)">
            <strong>Contraindications:</strong> Sound gatherings are generally gentle, but are not recommended for those with recent cranial injury, uncontrolled epilepsy, or serious psychiatric conditions without clinician approval. Please consult your care team or reach out at {{EMAIL}} for guidance.
          </div>
        </div>
      </section>

      <aside>
        <div class="panel">
          <h3>Quick details</h3>
          <div class="info-list">
            <div class="info"><div class="kbd">60m</div><div><strong>Session length</strong><div class="meta">Arrive 10 minutes early for settling.</div></div></div>
            <div class="info"><div class="kbd">Group</div><div><strong>Format</strong><div class="meta">Typically 6–14 people</div></div></div>
            <div class="info"><div class="kbd">Bring</div><div><strong>Comfort items</strong><div class="meta">Blanket, pillow, water</div></div></div>
          </div>
          <div style="margin-top:16px">
            <a class="cta" href="book.html">Reserve a spot</a>
            <div style="margin-top:8px;font-size:13px;color:var(--muted)">Questions? Call <a href="tel:{{PHONE}}">{{PHONE}}</a></div>
          </div>
        </div>

        <div style="height:18px"></div>

        <div class="panel">
          <h3>Our approach</h3>
          <p class="meta">We use tuned bowls, chimes, and voice to create consistent, uncomplicated fields for easing habitual tension. Sessions emphasize predictability and accessibility rather than dramatic transformation.</p>
        </div>
      </aside>
    </div>
  </main>
  <footer>
    <div class="wrap">© <span id="year"></span> {{BUSINESS_NAME}} — {{TAGLINE}} • <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> • <a href="tel:{{PHONE}}">{{PHONE}}</a></div>
  </footer>

  <script>
    // testimonial rotation
    (function(){
      const items = [
        {text:'"I leave clearer and less reactive — a quieter baseline that lasts a few days."',author:'— L., member'},
        {text:'"The group rhythm helped me show up for myself more consistently."',author:'— R., weekly attendee'},
        {text:'"Practical, subtle, reliable — exactly what I need between busy weeks."',author:'— K., member'}
      ];
      let idx=0;const tText=document.getElementById('t-text');const tAuthor=document.getElementById('t-author');
      const dotsEl=document.getElementById('dots');
      function renderDots(){dotsEl.innerHTML='';items.forEach((_,i)=>{const d=document.createElement('div');d.className='dot'+(i===idx?' active':'');d.addEventListener('click',()=>{idx=i;show();resetTimer()});dotsEl.appendChild(d)})}
      function show(){tText.style.opacity=0;tAuthor.style.opacity=0;setTimeout(()=>{tText.textContent=items[idx].text;tAuthor.textContent=items[idx].author;tText.style.opacity=1;tAuthor.style.opacity=1;renderDots()},250)}
      let timer=setInterval(()=>{idx=(idx+1)%items.length;show()},4500);
      function resetTimer(){clearInterval(timer);timer=setInterval(()=>{idx=(idx+1)%items.length;show()},4500)}
      renderDots();show();
    })();

    // footer year
    document.getElementById('year').textContent=new Date().getFullYear();
  </script>
</body>
</html>"} 
{"path":"faq.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>FAQ — {{BUSINESS_NAME}}</title>
  <meta name="description" content="Frequently asked questions about our sound sessions, membership, and bookings in {{CITY}}, {{STATE}}.">
  <style>
    :root{--bg:#f7ffff;--panel:#ffffff;--muted:#647d7d;--accent:#1f6d6e;--accent-2:#7bd7d5;--shadow:0 8px 24px rgba(10,30,30,0.06);font-family:Inter, system-ui, -apple-system, 'Segoe UI', Roboto, Arial}
    body{margin:0;background:var(--bg);color:#042a2b}
    header{padding:20px 0;background:linear-gradient(180deg,rgba(255,255,255,0.6),transparent);border-bottom:1px solid rgba(0,0,0,0.03)}
    .wrap{max-width:1100px;margin:0 auto;padding:0 20px}
    nav{display:flex;gap:12px;align-items:center}
    .brand{font-weight:800;color:var(--accent)}
    nav a{color:#063238;text-decoration:none;padding:6px 8px;border-radius:8px}
    nav a.active{background:var(--accent-2);color:#003437}

    main{max-width:1100px;margin:28px auto;padding:0 20px}
    .grid{display:grid;grid-template-columns:1fr 320px;gap:20px}
    .panel{background:var(--panel);padding:20px;border-radius:12px;box-shadow:var(--shadow)}
    h1{margin:0 0 8px}
    .faq-item{margin-bottom:14px}
    .q{font-weight:700}
    .a{color:var(--muted);margin-top:6px}
    .note{font-size:13px;color:var(--muted);margin-top:8px}

    /* pricing comparator */
    .comparator{display:flex;gap:10px;align-items:center;margin-top:12px}
    .toggle{background:#eef9f8;padding:6px;border-radius:30px;display:flex}
    .switch{background:white;padding:8px 14px;border-radius:20px;cursor:pointer;font-weight:700;color:var(--accent)}
    .price{font-size:28px;font-weight:800;color:#042a2b}
    .per{font-size:13px;color:var(--muted)}

    /* proof mini */
    .mini-proof{margin-top:18px;display:flex;flex-direction:column;gap:10px}
    .mini-test{display:flex;gap:10px;align-items:center}
    .avatar{width:44px;height:44px;border-radius:10px;background:linear-gradient(135deg,var(--accent-2),var(--accent));display:flex;align-items:center;justify-content:center;color:white;font-weight:700}
    .cred{display:flex;gap:8px;margin-top:8px}
    .cred .badge{background:#ffffff;border-radius:10px;padding:8px 10px;color:#0b4b4b;font-weight:700}
  </style>
</head>
<body>
  <header>
    <div class="wrap">
      <nav>
        <div class="brand">{{BUSINESS_NAME}}</div>
        <div style="flex:1"></div>
        <a href="index.html">Home</a>
        <a href="events.html">Sessions</a>
        <a href="private-sessions.html">Private</a>
        <a href="pricing.html">Rates</a>
        <a href="about.html">About</a>
        <a href="faq.html" class="active">Need-to-know</a>
        <a href="book.html">Reserve</a>
        <a href="contact.html">Contact</a>
      </nav>
    </div>
  </header>
  <main>
    <div class="grid wrap">
      <section>
        <div class="panel">
          <h1>Common questions and clear answers</h1>
          <p class="note">Short, direct answers so you can decide with confidence. For anything else, reach us at <a href="mailto:{{EMAIL}}">{{EMAIL}}</a>.</p>

          <div style="margin-top:18px">
            <div class="faq-item">
              <div class="q">What should I bring?</div>
              <div class="a">Comfortable clothing, a blanket or mat, and a small pillow if you like. We provide mats on request.</div>
            </div>

            <div class="faq-item">
              <div class="q">Are sessions safe for people with hearing sensitivity?</div>
              <div class="a">Yes — we work to keep sound levels moderate and predictable. If you have hyperacusis or other sensitivity, contact us in advance to arrange a partial-masked spot or a seat at the edge of the room.</div>
            </div>

            <div class="faq-item">
              <div class="q">Do I need to be a skilled listener or meditator?</div>
              <div class="a">No. Sessions are structured to be accessible whether you practice daily or are entirely new to sound work.</div>
            </div>

            <div class="faq-item">
              <div class="q">Can I speak to staff about medical concerns?</div>
              <div class="a">Yes. We include a contraindication note: people with recent head trauma, uncontrolled seizure disorders, or acute psychiatric conditions should consult a clinician before attending. If unsure, email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a>.</div>
            </div>

            <div style="margin-top:20px">
              <strong>Pricing snapshot</strong>
              <div class="comparator" style="margin-top:8px">
                <div class="toggle" role="tablist" aria-label="pricing toggle">
                  <div id="opt-month" class="switch" role="tab" aria-selected="true">Monthly</div>
                  <div id="opt-package" class="switch" role="tab" aria-selected="false">5-Session Pack</div>
                </div>
                <div style="margin-left:12px">
                  <div class="price" id="price-num">$35</div>
                  <div class="per" id="price-sub">per session</div>
                </div>
              </div>
              <div class="note">Numbers animate when you toggle for a quick comparison. Memberships and concessions available; full details on <a href="pricing.html">Rates</a>.</div>
            </div>

          </div>
        </div>

        <div style="height:18px"></div>

        <div class="panel" style="margin-top:18px">
          <h3>Booking & cancellation</h3>
          <p class="a">Members receive a 24-hour priority window. Standard cancellations up to 24 hours before receive a credit; late cancellations are held as attended. See booking page to reserve: <a href="book.html">Reserve a session</a>.</p>
        </div>

      </section>

      <aside>
        <div class="panel">
          <h3>Quick proof</h3>
          <div class="mini-proof">
            <div class="mini-test">
              <div class="avatar">J</div>
              <div>
                <div style="font-weight:700">"A reliable pause I actually keep."</div>
                <div class="meta">— J., member</div>
              </div>
            </div>

            <div class="cred">
              <div class="badge" tabindex="0" data-tip="Local health alliance membership">Health Partner</div>
              <div class="badge" tabindex="0" data-tip="Inclusive access policies in place">Access Friendly</div>
            </div>

            <div style="margin-top:12px;font-size:13px;color:var(--muted)">
              <strong>Need immediate help?</strong>
              <div>For urgent medical questions, contact your provider. For booking support, call <a href="tel:{{PHONE}}">{{PHONE}}</a>.</div>
            </div>
          </div>
        </div>

        <div style="height:18px"></div>

        <div class="panel">
          <h3>Still curious?</h3>
          <p class="a">Attend an open evening or book a private consult. Use the Reserve link to hold a spot.</p>
          <a href="book.html" style="display:inline-block;margin-top:8px;background:var(--accent);color:white;padding:10px;border-radius:10px;text-decoration:none;font-weight:700">Hold my spot</a>
        </div>
      </aside>
    </div>
  </main>

  <script>
    // pricing comparator with animated numbers
    (function(){
      const optMonth=document.getElementById('opt-month');
      const optPack=document.getElementById('opt-package');
      const priceNum=document.getElementById('price-num');
      const priceSub=document.getElementById('price-sub');

      let state='month';
      const prices={month:{val:35,sub:'per session'},pack:{val:150,sub:'for 5 sessions (effective $30 ea)'}};

      function animateTo(target){
        const start=Number(priceNum.textContent.replace(/[^0-9.]/g,''))||0;
        const end=target;const duration=420;const startTime=performance.now();
        function step(now){
          const t=Math.min(1,(now-startTime)/duration);
          const cur=Math.round((start+(end-start)*t)*100)/100;
          priceNum.textContent='$'+(cur%1?cur.toFixed(2):cur.toFixed(0));
          if(t<1)requestAnimationFrame(step);
        }
        requestAnimationFrame(step);
      }

      optMonth.addEventListener('click',()=>{optMonth.setAttribute('aria-selected','true');optPack.setAttribute('aria-selected','false');animateTo(prices.month.val);priceSub.textContent=prices.month.sub});
      optPack.addEventListener('click',()=>{optPack.setAttribute('aria-selected','true');optMonth.setAttribute('aria-selected','false');animateTo(prices.pack.val);priceSub.textContent=prices.pack.sub});
    })();

    // enable keyboard tooltip show for badges
    document.querySelectorAll('[data-tip]').forEach(el=>{el.addEventListener('focus',()=>{el.classList.add('hover')});el.addEventListener('blur',()=>{el.classList.remove('hover')})});
  </script>
</body>
</html>"} 
{"path":"book.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Reserve — {{BUSINESS_NAME}}</title>
  <meta name="description" content="Reserve a session or schedule a private visit. Membership options available.">
  <style>
    :root{--bg:#f3fbfb;--panel:#ffffff;--accent:#165c5c;--muted:#5f7c7b;--shadow:0 10px 30px rgba(8,30,30,0.06);font-family:Inter, system-ui, -apple-system, 'Segoe UI', Roboto, Arial}
    body{margin:0;background:var(--bg);color:#042d2d}
    header{padding:18px 0;border-bottom:1px solid rgba(0,0,0,0.04)}
    .wrap{max-width:1100px;margin:0 auto;padding:0 20px}
    nav{display:flex;gap:12px;align-items:center}
    .brand{font-weight:800;color:var(--accent)}
    nav a{color:#063238;text-decoration:none;padding:6px 8px;border-radius:8px}
    nav a.active{background:var(--accent);color:white}

    main{max-width:1100px;margin:28px auto;padding:0 20px}
    .grid{display:grid;grid-template-columns:1fr 340px;gap:20px}
    .panel{background:var(--panel);padding:20px;border-radius:12px;box-shadow:var(--shadow)}
    h1{margin:0 0 6px}
    p.lead{color:var(--muted);margin-top:6px}

    form{display:grid;gap:12px}
    label{font-weight:700;font-size:13px}
    input,select,textarea{padding:10px;border-radius:8px;border:1px solid #e6f0ef;font-size:14px}
    .row{display:flex;gap:10px}
    button{background:var(--accent);color:white;padding:10px 14px;border-radius:10px;border:0;font-weight:800;cursor:pointer}

    /* pricing comparator */
    .comparator{display:flex;gap:12px;align-items:center;margin-top:8px}
    .seg{display:flex;background:#eefbf9;padding:6px;border-radius:999px}
    .seg button{background:transparent;border:0;padding:8px 12px;border-radius:999px;cursor:pointer;font-weight:700}
    .seg button.active{background:var(--accent);color:white}
    .pricebox{padding:12px 14px;border-radius:10px;background:linear-gradient(180deg,#ffffff,#f2fbfa);font-weight:800}

    .calendar{display:flex;flex-direction:column;gap:8px}
    .event{display:flex;justify-content:space-between;align-items:center;padding:10px;border-radius:10px;background:#fbffff}
    .badge{background:#e9fffd;padding:6px 8px;border-radius:8px;color:var(--accent);font-weight:800}

  </style>
</head>
<body>
  <header>
    <div class="wrap">
      <nav>
        <div class="brand">{{BUSINESS_NAME}}</div>
        <div style="flex:1"></div>
        <a href="index.html">Home</a>
        <a href="events.html">Sessions</a>
        <a href="private-sessions.html">Private</a>
        <a href="pricing.html">Rates</a>
        <a href="about.html">About</a>
        <a href="faq.html">FAQ</a>
        <a href="book.html" class="active">Reserve</a>
        <a href="contact.html">Contact</a>
      </nav>
    </div>
  </header>

  <main>
    <div class="grid wrap">
      <section>
        <div class="panel">
          <h1>Reserve your place</h1>
          <p class="lead">Choose a session or a private consult. Memberships offer the best value for regular attendees.</p>

          <div style="margin-top:12px">
            <strong>Choose option</strong>
            <div class="comparator">
              <div class="seg" role="tablist">
                <button id="btn-single" class="active" role="tab">Single</button>
                <button id="btn-pack" role="tab">Pack</button>
                <button id="btn-member" role="tab">Member</button>
              </div>
              <div class="pricebox" id="pricebox">$35</div>
            </div>
          </div>

          <form id="book-form" style="margin-top:16px">
            <div class="row">
              <div style="flex:1">
                <label for="name">Full name</label>
                <input id="name" name="name" required>
              </div>
              <div style="flex:1">
                <label for="email">Email</label>
                <input id="email" name="email" type="email" required>
              </div>
            </div>
            <div class="row">
              <div style="flex:1">
                <label for="date">Choose date</label>
                <select id="date" name="date"></select>
              </div>
              <div style="flex:1">
                <label for="spots">Spots</label>
                <select id="spots" name="spots"><option>1</option><option>2</option><option>3</option></select>
              </div>
            </div>
            <label for="note">Notes or accessibility needs</label>
            <textarea id="note" name="note" rows="3"></textarea>

            <div style="display:flex;gap:10px;align-items:center;margin-top:12px">
              <button type="submit">Confirm & hold</button>
              <div style="color:var(--muted);font-size:13px">You will receive an email confirmation. Need help? <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
            </div>
          </form>

          <div style="margin-top:14px;font-size:13px;color:var(--muted)">
            <strong>Contraindications:</strong> If you have recent cranial injury, uncontrolled epilepsy, or are in acute psychiatric crisis, please consult your clinician before attending. Email any concerns to <a href="mailto:{{EMAIL}}">{{EMAIL}}</a>.
          </div>
        </div>

      </section>

      <aside>
        <div class="panel">
          <h3>Next events</h3>
          <div class="calendar" id="calendar">
            <!-- events populated by JS -->
          </div>
          <div style="margin-top:12px;font-size:13px;color:var(--muted)">See the full calendar on <a href="events.html">Sessions</a>.</div>
        </div>

        <div style="height:18px"></div>

        <div class="panel">
          <h3>Credibility & quick proof</h3>
          <div style="display:flex;flex-direction:column;gap:8px">
            <div style="display:flex;gap:8px;align-items:center">
              <div style="width:46px;height:46px;border-radius:10px;background:linear-gradient(135deg,var(--accent),var(--accent-2));display:flex;align-items:center;justify-content:center;color:white;font-weight:800">TS</div>
              <div>
                <div style="font-weight:800">Trustworthy sessions</div>
                <div style="color:var(--muted);font-size:13px">Low-volume, consistent cues.</div>
              </div>
            </div>

            <div style="display:flex;gap:8px">
